import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface MediaItem {
  id: string;
  type: "image";
  url: string;
  alt?: string;
  source: "upload";
  note?: string;
}

/** A parsed section from the brief markdown (e.g. ## Attitude → { heading, body }). */
export interface BriefSection {
  heading: string;
  body: string;
}

/** Parse a markdown brief into an array of sections, preserving all headings. */
export function parseBriefSections(md: string): BriefSection[] {
  return md
    .split(/^## /m)
    .filter(Boolean)
    .map((block) => {
      const newline = block.indexOf("\x0a");
      if (newline === -1) return { heading: block.trim(), body: "" };
      return {
        heading: block.substring(0, newline).trim(),
        body: block.substring(newline + 1).trim(),
      };
    });
}
